/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  if (input.status === "done") {
    const blockerIds = await dependencyRepo.listBlockerIds(input.orgId, before.id);
    const openBlockers: IssueId[] = [];
    for (const blockerId of blockerIds) {
      const blocker = await issueRepo.findIssueById(input.orgId, blockerId);
      if (
        blocker !== null &&
        blocker.archivedAt === null &&
        blocker.status !== "done" &&
        blocker.status !== "canceled"
      ) openBlockers.push(blockerId);
    }
    if (openBlockers.length > 0) throw new IssueBlockedError(openBlockers);
  }

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}
